<section class="admin-header"><div><p class="eyebrow">Catalogo</p><h1>Productos</h1></div><a class="button" href="/SS_NOVA_TECHNOLOGY/public/admin/products/form">Nuevo producto</a></section>
<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoria</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
<?php foreach ($products as $product): ?><tr>
    <td><div class="product-cell"><?php if (!empty($product['image_path'])): ?><img src="/SS_NOVA_TECHNOLOGY/public/<?= htmlspecialchars($product['image_path'], ENT_QUOTES, 'UTF-8') ?>" alt="<?= htmlspecialchars($product['name'], ENT_QUOTES, 'UTF-8') ?>"><?php else: ?><span class="image-placeholder">+</span><?php endif; ?><strong><?= htmlspecialchars($product['name'], ENT_QUOTES, 'UTF-8') ?></strong></div></td><td><?= htmlspecialchars($product['category_name'], ENT_QUOTES, 'UTF-8') ?></td><td>$ <?= number_format((float) $product['price'], 2, ',', '.') ?></td><td><?= (int) $product['stock'] ?></td><td><?= (bool) $product['is_active'] ? 'Activo' : 'Inactivo' ?></td>
    <td class="actions"><a href="/SS_NOVA_TECHNOLOGY/public/admin/products/form?id=<?= (int) $product['id'] ?>">Editar</a><form method="post" action="/SS_NOVA_TECHNOLOGY/public/admin/products/delete" onsubmit="return confirm('¿Eliminar este producto?');"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><button type="submit">Eliminar</button></form><form method="post" action="/SS_NOVA_TECHNOLOGY/public/admin/products/toggle"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $product['id'] ?>"><button type="submit"><?= (bool) $product['is_active'] ? 'Desactivar' : 'Activar' ?></button></form></td>
</tr><?php endforeach; ?></tbody></table></div>